import 'server-only';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import type { DataFile, Franchise, Person, Show } from './types';

const DATA_FILE = path.join(process.cwd(), 'data', 'shows.json');

let data: DataFile | undefined;

/** Reads the data generated by `npm run data`. Runs at build time only. */
export function getData(): DataFile {
    if (!data) {
        try {
            data = JSON.parse(readFileSync(DATA_FILE, 'utf8')) as DataFile;
        } catch (error) {
            throw new Error(
                `Could not read ${DATA_FILE}. Run \`npm run data\` first.`,
                { cause: error }
            );
        }
    }
    return data;
}

export const getShows = () => getData().shows;

export const getShow = (id: string): Show | undefined =>
    getShows().find((show) => show.id === id);

export const getFranchises = () => getData().franchises;

export const getFranchise = (id: string): Franchise | undefined =>
    getFranchises().find((franchise) => franchise.id === id);

/** None in data built before people were added. */
export const getPeople = (): Person[] => getData().people ?? [];

export const getPerson = (id: string): Person | undefined =>
    getPeople().find((person) => person.id === id);
